#!/usr/bin/env node
/**
 * Give a fresh clone a `web/src/lib/deployments.ts` so the web app can be
 * type-checked and unit-tested before any chain exists.
 *
 * THE PROBLEM THIS REMOVES. That file is generated by `rocketh-export` and is
 * gitignored, because it names a chain and its addresses and therefore belongs
 * to whoever deployed rather than to the repo. But `deployments-store.ts`
 * imports it statically, and the app's types are derived from it
 * (`TypedDeployments = typeof initialDeployments`), so without it a clone
 * cannot run `pnpm check` or `pnpm test:unit` at all: it fails with 23
 * svelte-check errors and eight unresolvable test files, none of which name the
 * actual cause. `pnpm test` appeared to work only because the e2e script
 * compiles, deploys and exports inside its own worktree.
 *
 * WHAT IT DOES. Nothing, when the file is already there: a developer's export
 * for their own chain always wins, and this must never overwrite it (a
 * `pnpm start` session rewrites that file continuously). Otherwise it exports
 * from the deployment records COMMITTED to this repo, which is enough because
 * a record carries the addresses and ABIs; no compiler, no node, no network.
 *
 * WHY THIS IS NOT A STUB. A hand-written placeholder would have to name the
 * app's contracts to satisfy the types, so it would be a second copy of the
 * deployment shape that goes stale the moment a contract changes. Exporting the
 * real records keeps one source of truth and costs about a second.
 *
 * It never fails the install. A fork that has committed no deployment records
 * is in a legitimate state, and an install that dies on it would be a worse
 * first experience than the one this exists to fix, so it explains itself and
 * gets out of the way.
 */
import {execFileSync} from 'node:child_process';
import {existsSync, readdirSync, statSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const target = join(root, 'web', 'src', 'lib', 'deployments.ts');
const deploymentsDir = join(root, 'contracts', 'deployments');

if (existsSync(target)) process.exit(0);

/**
 * The networks this repo ships records for.
 *
 * Read from disk rather than hardcoded, so a fork that commits its own network
 * is served by the same script without editing it. `localhost` and the other
 * throwaway chains are gitignored (see contracts/.gitignore), so what is left
 * here is exactly the set somebody chose to keep.
 */
const networks = existsSync(deploymentsDir)
	? readdirSync(deploymentsDir).filter((name) =>
			statSync(join(deploymentsDir, name)).isDirectory(),
		)
	: [];

if (networks.length === 0) {
	console.warn(
		'[ensure-deployments] No committed deployment records, so web/src/lib/deployments.ts\n' +
			'                    was not generated. `pnpm check` and `pnpm test:unit` will fail\n' +
			'                    until you deploy: `pnpm start`, or\n' +
			'                    `pnpm contracts:compile && pnpm contracts:deploy <network>`.',
	);
	process.exit(0);
}

for (const network of networks) {
	try {
		execFileSync(
			'pnpm',
			[
				'--filter',
				'./contracts',
				'export',
				network,
				'--ts',
				'../web/src/lib/deployments.ts',
			],
			{cwd: root, stdio: 'pipe'},
		);
		if (existsSync(target)) {
			console.log(
				`[ensure-deployments] Generated web/src/lib/deployments.ts from the committed ` +
					`${network} records, so the web app type-checks before you deploy anything. ` +
					`Deploying overwrites it.`,
			);
			process.exit(0);
		}
	} catch {
		// Try the next network. Reported once, below, if none work.
	}
}

console.warn(
	'[ensure-deployments] Could not export any of the committed deployment records ' +
		`(${networks.join(', ')}), so web/src/lib/deployments.ts was not generated. ` +
		'`pnpm check` and `pnpm test:unit` will fail until you deploy.',
);
